<script setup lang="ts">
import { computed, ref } from 'vue'
import { Bar, Line } from 'vue-chartjs'
import { BarElement, CategoryScale, Chart as ChartJS, Filler, Legend, LineElement, LinearScale, PointElement, Tooltip } from 'chart.js'
import metrics from '../data/metrics.json'

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Tooltip, Legend, Filler)
type Month = (typeof metrics.months)[number]
const selectedMonth = ref('All')
const monthOptions = ['All', ...metrics.months.map((month) => month.month)]
const catalog = [
  ['BR-1042', 'The Celeste', 'A-line', 'Silk mikado', 2890, 'https://images.unsplash.com/photo-1594552072238-b8a33785b261?auto=format&fit=crop&w=240&q=80'],
  ['BR-1187', 'The Margot', 'Ballgown', 'Italian satin', 3250, 'https://images.unsplash.com/photo-1622277430358-f4d134452e2e?auto=format&fit=crop&w=240&q=80'],
  ['BR-1264', 'The Josephine', 'Mermaid', 'French lace', 2780, 'https://images.unsplash.com/photo-1549417229-7686ac5595fd?auto=format&fit=crop&w=240&q=80'],
  ['BR-1321', 'The Beatrice', 'Trumpet', 'Crepe charmeuse', 2640, 'https://images.unsplash.com/photo-1532454781337-fc3edff34f91?auto=format&fit=crop&w=240&q=80'],
  ['BR-1419', 'The Florence', 'A-line', 'Tulle & lace', 2410, 'https://images.unsplash.com/photo-1591604466107-ec97de577aff?auto=format&fit=crop&w=240&q=80'],
  ['BR-1536', 'The Elodie', 'Sheath', 'Matte crepe', 2260, 'https://images.unsplash.com/photo-1511288702291-e55d6cfbe3b5?auto=format&fit=crop&w=240&q=80'],
  ['BR-1672', 'The Louise', 'Ballgown', 'Organza', 2180, 'https://images.unsplash.com/photo-1549416878-b9ca95e26903?auto=format&fit=crop&w=240&q=80'],
  ['BR-1728', 'The Clara', 'Mermaid', 'Chantilly lace', 2050, 'https://images.unsplash.com/photo-1631234764568-996fab371596?auto=format&fit=crop&w=240&q=80'],
  ['BR-1854', 'The Iris', 'Trumpet', 'Chiffon', 1890, 'https://images.unsplash.com/photo-1617724975854-70b5d0cedb0a?auto=format&fit=crop&w=240&q=80'],
  ['BR-1931', 'The Marguerite', 'Sheath', 'Duchess satin', 1750, 'https://images.unsplash.com/photo-1529636273736-fc88b31ea9d9?auto=format&fit=crop&w=240&q=80'],
]
const activeMonths = computed(() => selectedMonth.value === 'All' ? metrics.months : metrics.months.filter((month) => month.month === selectedMonth.value))
const index = computed(() => selectedMonth.value === 'All' ? 11 : metrics.months.findIndex((month) => month.month === selectedMonth.value))
const previous = computed(() => index.value > 0 ? metrics.months[index.value - 1] : undefined)
const salesOf = (months: Month[]) => months.reduce((sum, month) => sum + month.salesBySku.reduce((monthSum, sale) => monthSum + sale.amount, 0), 0)
const overallSales = computed(() => salesOf(activeMonths.value))
const seasonalSales = computed(() => activeMonths.value.reduce((sum, month) => sum + month.seasonalSales, 0))
const promoLift = computed(() => activeMonths.value.reduce((sum, month) => sum + month.promoLift, 0) / activeMonths.value.length)
const inventoryTurn = computed(() => activeMonths.value.reduce((sum, month) => sum + month.inventoryTurn, 0) / activeMonths.value.length)
const change = (metric: 'sales' | 'seasonalSales' | 'promoLift' | 'inventoryTurn') => {
  if (selectedMonth.value === 'All' || !previous.value) return null
  const now = metric === 'sales' ? salesOf(activeMonths.value) : activeMonths.value[0][metric]
  const before = metric === 'sales' ? salesOf([previous.value]) : previous.value[metric]
  return ((now - before) / before) * 100
}
const skuTotals = computed(() => {
  const totals = new Map<string, number>()
  activeMonths.value.forEach((month) => month.salesBySku.forEach((sale) => totals.set(sale.sku, (totals.get(sale.sku) ?? 0) + sale.amount)))
  return [...totals].sort((a, b) => b[1] - a[1])
})
const dress = (sku: string) => { const item = catalog.find((entry) => entry[0] === sku)!; return { sku: String(item[0]), name: String(item[1]), style: String(item[2]), fabric: String(item[3]), price: Number(item[4]), image: String(item[5]) } }
const best = computed(() => skuTotals.value.slice(0, 5).map(([sku]) => dress(sku)))
const slow = computed(() => skuTotals.value.slice(-5).reverse().map(([sku]) => dress(sku)))
const amount = (sku: string) => skuTotals.value.find(([key]) => key === sku)?.[1] ?? 0
const trend = (sku: string) => {
  const before = selectedMonth.value === 'All' ? metrics.months[0].salesBySku.find((sale) => sale.sku === sku)?.amount ?? 0 : previous.value?.salesBySku.find((sale) => sale.sku === sku)?.amount ?? 0
  const now = selectedMonth.value === 'All' ? metrics.months[11].salesBySku.find((sale) => sale.sku === sku)?.amount ?? 0 : amount(sku)
  return before ? ((now - before) / before) * 100 : 0
}
const money = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value)
const compact = (value: number) => value >= 1000000 ? `$${(value / 1000000).toFixed(2)}M` : `$${Math.round(value / 1000)}K`
const delta = (value: number | null) => value === null ? 'Year view' : `${value >= 0 ? 'Up' : 'Down'} ${Math.abs(value).toFixed(1)}% vs prev.`
const salesChart = computed(() => ({ labels: metrics.months.map((month) => month.month), datasets: [{ data: metrics.months.map((month) => salesOf([month])), backgroundColor: metrics.months.map((month) => selectedMonth.value === month.month ? '#6d9eaf' : '#c9dfe3'), borderRadius: 4 }] }))
const lineChart = computed(() => ({ labels: metrics.months.map((month) => month.month), datasets: [{ label: 'Seasonal sales', data: metrics.months.map((month) => month.seasonalSales), borderColor: '#6d9eaf', backgroundColor: 'rgba(109,158,175,.12)', fill: true, tension: .35, pointRadius: 3 }, { label: 'Promo lift', data: metrics.months.map((month) => month.promoLift * 20000), borderColor: '#c58e72', borderDash: [5, 5], tension: .35, pointRadius: 2 }] }))
const chartOptions = { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { grid: { display: false } }, y: { grid: { color: '#e7eeee' }, ticks: { callback: (value: string | number) => `$${Number(value) / 1000}K` } } } }
</script>

<template>
  <v-app-bar class="topbar" elevation="0" height="78"><div class="bar-inner"><div class="brand"><span class="brand-mark">A</span><span><b>Atelier North</b><small>Chicago · Buyer intelligence</small></span></div><div class="bar-actions"><span class="live"><i></i>Live data · {{ metrics.year }}</span><v-select v-model="selectedMonth" :items="monthOptions" label="View period" variant="outlined" density="compact" hide-details class="month-select" prepend-inner-icon="mdi-calendar-month-outline" /></div></div></v-app-bar>
  <main class="page"><v-container fluid class="container"><header class="intro"><div><span class="kicker">Merchandising overview</span><h1>Know what moves<br><em>the aisle.</em></h1><p>A clear read on what Chicago brides are choosing, and what deserves more room on the floor.</p></div><div class="period"><small>SHOWING</small><b>{{ selectedMonth === 'All' ? 'Full year' : selectedMonth + ' 2025' }}</b><span></span>Updated today, 9:42 AM</div></header>
    <section class="metrics"><v-card v-for="item in [{ label: 'Overall sales', value: compact(overallSales), key: 'sales', note: 'total revenue' }, { label: 'Seasonal sales', value: compact(seasonalSales), key: 'seasonalSales', note: 'annual total' }, { label: 'Promo lift', value: promoLift.toFixed(1) + '%', key: 'promoLift', note: 'vs. base period' }, { label: 'Inventory turn', value: inventoryTurn.toFixed(1) + 'x', key: 'inventoryTurn', note: 'annualized pace' }]" :key="item.key" class="metric" elevation="0"><v-card-text><div class="metric-label"><span>{{ item.label }}</span><v-icon size="18">mdi-chart-line</v-icon></div><strong>{{ item.value }}</strong><div class="metric-note"><span :class="change(item.key as 'sales' | 'seasonalSales' | 'promoLift' | 'inventoryTurn') !== null && change(item.key as 'sales' | 'seasonalSales' | 'promoLift' | 'inventoryTurn')! < 0 ? 'down' : 'up'">{{ delta(change(item.key as 'sales' | 'seasonalSales' | 'promoLift' | 'inventoryTurn')) }}</span><small>{{ selectedMonth === 'All' && item.key === 'seasonalSales' ? 'annual total' : item.note }}</small></div></v-card-text></v-card></section>
    <section class="charts"><v-card class="panel" elevation="0"><v-card-text><div class="heading"><div><span class="kicker">Performance pulse</span><h2>Sales, at a glance</h2></div><span class="legend">Sales · Promo lift</span></div><div class="chart"><Bar :data="salesChart" :options="chartOptions" /></div></v-card-text></v-card><v-card class="panel" elevation="0"><v-card-text><div class="heading"><div><span class="kicker">Seasonality</span><h2>The shape of the year</h2></div><span class="tag">Chicago store</span></div><div class="chart"><Line :data="lineChart" :options="chartOptions" /></div></v-card-text></v-card></section>
    <header class="section-header"><div><span class="kicker">Assortment signal</span><h2>What brides are reaching for</h2></div><small>Ranked by {{ selectedMonth === 'All' ? 'full-year' : selectedMonth }} sales</small></header>
    <section class="dress-grid"><v-card v-for="(group, groupIndex) in [best, slow]" :key="groupIndex" class="panel" elevation="0"><v-card-text><div class="heading"><div><span class="kicker">{{ groupIndex ? 'Needs attention' : 'Top performers' }}</span><h2>{{ groupIndex ? 'The slower movers' : 'The best sellers' }}</h2></div><v-icon>{{ groupIndex ? 'mdi-arrow-bottom-left' : 'mdi-arrow-top-right' }}</v-icon></div><div class="dress-list"><div v-for="item in group" :key="item.sku" class="dress"><img :src="item.image" :alt="item.name"><div><b>{{ item.name }}</b><small>{{ item.sku }} · {{ item.style }} · {{ item.fabric }}</small><span>{{ money(item.price) }} <i :class="trend(item.sku) < 0 ? 'down' : 'up'">{{ trend(item.sku) >= 0 ? '↑' : '↓' }} {{ Math.abs(trend(item.sku)).toFixed(1) }}%</i></span></div><strong>{{ money(amount(item.sku)) }}<small>sales</small></strong></div></div></v-card-text></v-card></section>
    <section class="recommendation"><div><span class="kicker">Buyer's note</span><h2>Make room for<br><em>the next yes.</em></h2><p>Across higher-performing locations, romantic structure is winning the appointment. Prioritize tactile fabrics and silhouettes that photograph beautifully.</p></div><div class="recommendation-list"><div><b>01 · Bring in more lace mermaids</b><p>French lace is outperforming other fabrics by 14% across peer stores.</p></div><div><b>02 · Protect your mikado A-line depth</b><p>Clean, structured shapes are converting best for spring appointments.</p></div><div><b>03 · Test soft organza accents</b><p>Ballgowns with light movement are picking up in Austin and Denver.</p></div></div></section>
  </v-container></main>
</template>

