k;margin:20px 0 19px;color:#29464c;font:400 39px Georgia,serif}.metric-note{display:flex;justify-content:space-between;gap:8px;color:#91a0a2;font-size:10px}.up{color:#5e9a7e}.down{color:#b8796e}.charts,.dress-grid{grid-template-columns:1fr 1fr;margin-top:28px}.panel .v-card-text{padding:25px}.heading{display:flex;align-items:flex-start;justify-content:space-between}.panel h2,.section-header h2{margin:7px 0 0;color:#29444a;font:400 25px Georgia,serif}.legend,.tag{color:#87989a;font-size:10px}.tag{padding:5px 9px;border:1px solid #d7e4e3;border-radius:20px}.chart{height:270px;margin-top:20px}.section-header{display:flex;align-items:end;justify-content:space-between;margin:64px 0 20px}.section-header small{color:#94a1a3;font-size:11px}.dress-grid{margin-top:0}.dress-list{margin-top:22px}.dress{display:grid;grid-template-columns:54px minmax(0,1fr) auto;gap:12px;align-items:center;padding:13px 0;border-top:1px solid #edf2f1}.dress img{width:54px;height:64px;object-fit:cover;filter:saturate(.7)}.dress b{display:block;color:#36545a;font:600 14px Georgia,serif}.dress small{display:block;overflow:hidden;color:#91a0a2;font-size:10px;margin:5px 0 8px;text-overflow:ellipsis;white-space:nowrap}.dress span{color:#62787d;font-size:11px}.dress i{font-style:normal;margin-left:10px}.dress>strong{text-align:right;color:#38555a;font:600 14px Georgia,serif}.dress>strong small{margin:4px 0 0;color:#9aa7a8;font-weight:400}.recommendation{display:grid;grid-template-columns:.9fr 1.1fr;gap:70px;margin-top:64px;padding:45px 48px;background:#eaf2f1;border-top:1px solid #d6e5e3}.recommendation h2{margin:10px 0 16px;color:#29444a;font:400 34px/1.05 Georgia,serif}.recommendation p{max-width:370px;color:#6e8387;font-size:13px;line-height:1.7}.recommendation-list{padding-left:36px;border-left:1px solid #cbdedc}.recommendation-list>div{padding:17px 0;border-bottom:1px solid #d5e3e1}.recommendation-list>div:last-child{border-bottom:0}.recommendation-list b{color:#36545a;font:600 14px Georgia,serif}.recommendation-list p{margin-top:5px;font-size:11px}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.charts,.dress-grid,.recommendation{grid-template-columns:1fr}.recommendation-list{padding:20px 0 0;border-top:1px solid #cbdedc;border-left:0}.intro{align-items:flex-start;flex-direction:column;gap:25px}}@media(max-width:600px){.bar-inner{padding:0 16px}.brand small,.live{display:none}.bar-actions{gap:8px}.month-select{width:145px}.container{padding:35px 16px 55px}.intro h1{font-size:46px}.metrics{gap:8px}.metric{min-height:145px}.metric .v-card-text{padding:16px 14px}.metric strong{font-size:29px;margin:18px 0 14px}.metric-note{align-items:flex-start;flex-direction:column}.panel .v-card-text{padding:18px 14px}.chart{height:220px}.section-header{align-items:flex-start;flex-direction:column;gap:10px;margin-top:42px}.recommendation{gap:30px;margin-top:42px;padding:30px 22px}.dress{grid-template-columns:45px minmax(0,1fr)}.dress img{width:45px;height:57px}.dress>strong{grid-column:2;text-align:left;margin-top:-8px}}
